import { readFileSync } from 'node:fs';
import {unpackArchiveTransfer} from './archive-transfer.mjs';
import assert from 'node:assert/strict';
import { auditQiluPublicArchive, sha256 } from './audit-qilu-public-archive.mjs';
const original=JSON.parse(unpackArchiveTransfer(readFileSync(new URL('../../tests/fixtures/cloud-pilot/qilu-retained-public-archive.transfer.json',import.meta.url)),'dceb72af5ff029b8810d8d30b6abacf09f7a117f279f3f264aa7fe548f761f8a',1729217));
const rule=JSON.parse(readFileSync(new URL('./qilu-public-archive-rule.json',import.meta.url)));
const opts={expected:original.sidecar,sourceConfigSha256:rule.sourceConfigSha256,rule};
const results=[];
const test=(name,fn)=>{try{fn();results.push({name,status:'PASS'});}catch(e){results.push({name,status:'FAIL',message:e.message});}};
const run=(bundle,options=opts)=>auditQiluPublicArchive(bundle,options);
const clone=()=>structuredClone(original);
const body=(b,key)=>{const a=b.sidecar.artifacts.find(a=>a.logicalKey===key);return Buffer.concat(b.files.find(f=>f.path===a.path).chunks.map(c=>Buffer.from(c,'base64')));};
const replace=(b,key,bytes)=>{const a=b.sidecar.artifacts.find(a=>a.logicalKey===key),f=b.files.find(f=>f.path===a.path);a.sha256=f.sha256=sha256(bytes);a.byteCount=f.byteCount=bytes.length;f.chunks=[];for(let i=0;i<bytes.length;i+=576)f.chunks.push(bytes.subarray(i,i+576).toString('base64'));};
const pageKey='qilu-non-marketing-beisen-page-0000';
const mutateRow=(b,fn)=>{const json=JSON.parse(body(b,pageKey));fn(json.Data[0]);replace(b,pageKey,Buffer.from(JSON.stringify(json)));};
const deny=(name,fn,error)=>test(name,()=>{const b=clone();fn(b);assert.throws(()=>run(b),error);});
test('retained exact public archive passes',()=>assert.equal(run(original).status,'PASS'));
test('explicit live evidence subdirectory passes',()=>{const b=clone();b.sidecar.evidenceSubdirectory='cloud-pilot/runtime-evidence';for(const a of b.sidecar.artifacts)a.path=a.path.replace('/private/runtime-evidence/','/cloud-pilot/runtime-evidence/');for(const f of b.files)f.path=f.path.replace('/private/runtime-evidence/','/cloud-pilot/runtime-evidence/');assert.equal(run(b,{...opts,expected:{...opts.expected,evidenceSubdirectory:'cloud-pilot/runtime-evidence'}}).status,'PASS');});
test('fresh public vacancy title with matching metadata passes',()=>{const b=clone();mutateRow(b,r=>r.JobAdName='合规岗位信息更新');const a=b.sidecar.artifacts.find(a=>a.logicalKey===pageKey),m=JSON.parse(body(b,'qilu-partition-metadata'));m.partitions[1].evidence.artifacts[0].bodySha256=a.sha256;m.partitions[1].evidence.pages[0].responseFingerprintSha256=a.sha256;replace(b,'qilu-partition-metadata',Buffer.from(JSON.stringify(m)));assert.equal(run(b).status,'PASS');});
deny('new applicant field fails closed',b=>mutateRow(b,r=>r.ApplicantName='Example'),/UNKNOWN_OR_MISSING_FIELD/);
deny('new session field fails closed',b=>mutateRow(b,r=>r.SessionId='synthetic-session'),/UNKNOWN_OR_MISSING_FIELD/);
deny('personalized application state rejected',b=>mutateRow(b,r=>r.IsDelivered=true),/UNREVIEWED_ROW_DEFAULT/);
deny('previously-null QR contact rejected',b=>mutateRow(b,r=>r.WorkWeChatQrCode='https://example.test/qr'),/ROW_FIELD_TYPE/);
deny('session string in duty rejected',b=>mutateRow(b,r=>r.Duty='session_id=synthetic'),/CREDENTIAL_OR_SESSION_MARKER/);
deny('contact email in duty rejected',b=>mutateRow(b,r=>r.Duty='test@example.test'),/UNREVIEWED_PERSONAL_OR_CONTACT_DATA/);
deny('encoded email in duty rejected',b=>mutateRow(b,r=>r.Duty='test&#64;example.test'),/UNREVIEWED_PERSONAL_OR_CONTACT_DATA/);
deny('named contact marker in duty rejected',b=>mutateRow(b,r=>r.Duty='联系人：Example'),/UNREVIEWED_PERSONAL_DATA_TERMINOLOGY/);
deny('body markup rejected',b=>mutateRow(b,r=>r.Duty='<input value="private">'),/UNREVIEWED_BODY_MARKUP/);
deny('duplicate JSON keys rejected',b=>replace(b,pageKey,Buffer.from(body(b,pageKey).toString().replace('{','{"Data":[],',1))),/UNREVIEWED_JSON_SERIALIZATION/);
test('public HTML metadata and vacancy text changes are not frozen to yesterday',()=>{const b=clone(),key='qilu-marketing-official-html-page-0000';const changed=body(b,key).toString().replace('<head>','<head><meta property="og:type" content="website"/>').replace('医学经理2','医学经理3').replace(/"traceId":"[a-f0-9-]+"/,'"traceId":"12345678-1234-4234-8234-123456789abc"');replace(b,key,Buffer.from(changed));const a=b.sidecar.artifacts.find(a=>a.logicalKey===key),m=JSON.parse(body(b,'qilu-partition-metadata'));m.partitions[0].evidence.artifacts[0].bodySha256=a.sha256;m.partitions[0].evidence.pages[0].responseFingerprintSha256=a.sha256;replace(b,'qilu-partition-metadata',Buffer.from(JSON.stringify(m)));assert.equal(run(b).status,'PASS');});
for(const [label,injection] of [['credential','<script>window.access_token="synthetic-private-token";</script>'],['session','<script>window.sessionId="synthetic-session";</script>'],['applicant','<script>window.applicantName="Example";</script>'],['password input','<input type="password" value="synthetic-private">'],['hidden token','<input type="hidden" name="csrf_token" value="synthetic-private">'],['personalized email input','<input name="email" value="private@example.test">'],['encoded URL token','<a href="https://example.test/?access%5Ftoken=synthetic">link</a>'],['client secret','<script>window.client_secret="synthetic";</script>'],['concatenated credential','<script>window.access_token=""+"synthetic";</script>'],['opaque personalized payload','<script>window.applicantData=decodeState("synthetic");</script>'],['meta property token','<meta property="access_token" content="synthetic-secret">'],['template literal credential','<script>window.access_token=`synthetic-secret`;</script>'],['userInfo payload','<script>window.userInfo={name:"Example",email:"private@example.test"};</script>'],['encoded key','<script>window["access\\u005ftoken"]="synthetic-private";</script>']])deny('HTML '+label+' fails privacy review',b=>replace(b,'qilu-marketing-official-html-page-0000',Buffer.from(body(b,'qilu-marketing-official-html-page-0000').toString().replace('</head>',injection+'</head>'))),/HTML_SENSITIVE_DATA/);
deny('request header baggage rejected',b=>{b.sidecar.artifacts[0].headers={Cookie:'synthetic'};},/UNKNOWN_OR_MISSING_FIELD/);
deny('metadata header baggage rejected',b=>{const m=JSON.parse(body(b,'qilu-partition-metadata'));m.partitions[0].evidence.artifacts[0].headers={Authorization:'synthetic'};replace(b,'qilu-partition-metadata',Buffer.from(JSON.stringify(m)));},/UNKNOWN_OR_MISSING_FIELD/);
deny('metadata body hidden property rejected',b=>{const m=JSON.parse(body(b,'qilu-partition-metadata'));m.unrelated='synthetic';replace(b,'qilu-partition-metadata',Buffer.from(JSON.stringify(m)));},/UNKNOWN_OR_MISSING_FIELD/);
deny('wrong source URL rejected',b=>{b.sidecar.artifacts[0].requestedUrl='https://example.test/';},/PUBLIC_RESPONSE_ENVELOPE/);
deny('unrelated artifact type rejected',b=>{b.sidecar.artifacts[0].kind='SCREENSHOT';},/CHANNEL_AND_KIND/);
deny('extra arbitrary file rejected',b=>{b.files.push(structuredClone(b.files[0]));},/ARTIFACT_SET_SIZE/);
deny('changed raw bytes with old hash rejected',b=>{b.files[0].chunks[0]=Buffer.alloc(576).toString('base64');},/BODY_BYTES/);
deny('unexpected evidence directory rejected',b=>{b.sidecar.evidenceSubdirectory='other';},/EVIDENCE_DIRECTORY/);
test('wrong current source configuration rejected',()=>assert.throws(()=>run(original,{...opts,sourceConfigSha256:'0'.repeat(64)}),/SOURCE_CONFIG_BINDING/));
test('wrong pending tuple rejected',()=>assert.throws(()=>run(original,{...opts,expected:{...opts.expected,batchId:'another'}}),/EXPECTED_TUPLE/));
test('audit does not mutate archive bytes',()=>{const before=JSON.stringify(original);run(original);assert.equal(JSON.stringify(original),before);});
console.log(JSON.stringify({passed:results.filter(r=>r.status==='PASS').length,total:results.length,failures:results.filter(r=>r.status==='FAIL')}));
if(results.some(r=>r.status==='FAIL'))process.exitCode=1;
